{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Untie input and output item embeddings across all four category models, initializing the output table as an exact copy without consuming additional initialization randomness. Both tables train jointly within each single NextItNet model. This tests whether separate encoding and target representations help the current configuration, despite regressions in earlier configurations. Preserve width, causal backbone, readout, dot-product scoring, loss and optimizer.",
      "edits": [
        {
          "find": "            nn.init.xavier_uniform_(self.pos_emb.weight)\n            self.pos_emb.weight[0].zero_()\n\n    def encode_sequence",
          "replace": "            nn.init.xavier_uniform_(self.pos_emb.weight)\n            self.pos_emb.weight[0].zero_()\n        self.output_item_emb = nn.Embedding.from_pretrained(\n            self.item_emb.weight.detach().clone(), freeze=False, padding_idx=0\n        )\n\n    def encode_sequence"
        },
        {
          "find": "        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)\n        neg_scores = (out * self.item_emb(neg)).sum(dim=-1)",
          "replace": "        pos_scores = (out * self.output_item_emb(pos)).sum(dim=-1)\n        neg_scores = (out * self.output_item_emb(neg)).sum(dim=-1)"
        },
        {
          "find": "        cand_emb = self.item_emb(candidates)",
          "replace": "        cand_emb = self.output_item_emb(candidates)"
        },
        {
          "find": "            \"sequence_readout\": \"causal_recent4_blend_0.2\",\n            \"residual_scale\": 0.5,",
          "replace": "            \"sequence_readout\": \"causal_recent4_blend_0.2\",\n            \"residual_scale\": 0.5,\n            \"item_embedding_parameterization\": \"untied_copy_initialized\","
        },
        {
          "find": "        if meta.get(\"residual_scale\") != 0.5:\n            raise RuntimeError(f\"Incompatible residual scale metadata for {ds}\")\n        model = ModelClass(",
          "replace": "        if meta.get(\"residual_scale\") != 0.5:\n            raise RuntimeError(f\"Incompatible residual scale metadata for {ds}\")\n        if meta.get(\"item_embedding_parameterization\") != \"untied_copy_initialized\":\n            raise RuntimeError(f\"Incompatible item embedding metadata for {ds}\")\n        model = ModelClass("
        }
      ]
    }
  ],
  "change_summary": "Separate jointly trained input/output embeddings with identical initialization; update predictor metadata checks. Retain one checkpoint per category and existing training settings."
}
